// Hoisted @string literals (single allocation; Go keeps these in RODATA)
internal static ref readonly @string sha1ˢ => ref sha1ˢᵇ;
private static readonly @string sha1ˢᵇ = "sha1"u8;

public static void TestGolden(ж<testing.T> t) {
    cryptotest.TestAllImplementations(t, sha1ˢ, testGolden);
}
internal static void testGolden(ж<testing.T> t) {
    for (nint i = 0; i < len(golden); i++) {
        var g = golden[i];
        @string s = fmt.Sprintf("%x"u8, Sum(slice<byte>(g.@in)));
        if (s != g.@out) {
            t.Fatalf("Sum function: sha1(%s) = %s want %s", g.@in, s, g.@out);
        }
        var c = New();
        for (nint j = 0; j < 4; j++) {
            slice<byte> sum = default;
            switch (j) {
            case 0 or 1: {
                io.WriteString(c, g.@in);
                sum = c.Sum(default);
                break;
            }
            case 2: {
                io.WriteString(c, g.@in.slice(0, len(g.@in) / 2));
                c.Sum(default);
                io.WriteString(c, g.@in.slice(len(g.@in) / 2));
                sum = c.Sum(default);
                break;
            }
            case 3: {
                if (boring.Enabled) {
                    continue;
                }
                io.WriteString(c, g.@in.slice(0, len(g.@in) / 2));
                c._<ж<global::go.crypto.sha1_package.digest>>().ConstantTimeSum(default);
                io.WriteString(c, g.@in.slice(len(g.@in) / 2));
                sum = c._<ж<global::go.crypto.sha1_package.digest>>().ConstantTimeSum(default);
                break;
            }}
            @string sΔ1 = fmt.Sprintf("%x"u8, sum);
            if (sΔ1 != g.@out) {
                t.Fatalf("sha1[%d](%s) = %s want %s", j, g.@in, sΔ1, g.@out);
            }
            c.Reset();
        }
    }
}

public static void TestGoldenMarshal(ж<testing.T> t) {
    cryptotest.TestAllImplementations(t, sha1ˢ, testGoldenMarshal);
}
internal static void testGoldenMarshal(ж<testing.T> t) {
    var h = New();
    var h2 = New();
    foreach (var (_, g) in range(golden)) {
        h.Reset();
        h2.Reset();

        io.WriteString(h, g.@in.slice(0, len(g.@in) / 2));

        var (state, err) = h._<encoding.BinaryMarshaler>().MarshalBinary();
        if (err != nil) {
            t.Errorf("could not marshal: %v", err);
            continue;
        }

        (var stateAppend, err) = h._<encoding.BinaryAppender>().AppendBinary(new slice<byte>(4, 32));
        if (err != nil) {
            t.Errorf("could not marshal: %v", err);
            continue;
        }
        stateAppend = stateAppend[4..];

        if (((sstring)state) != g.halfState) {
            t.Errorf("sha1(%q) state = %+q, want %+q", g.@in, state, g.halfState);
            continue;
        }

        if (((sstring)stateAppend) != g.halfState) {
            t.Errorf("sha1(%q) stateAppend = %+q, want %+q", g.@in, stateAppend, g.halfState);
            continue;
        }

        var errΔ1 = h2._<encoding.BinaryUnmarshaler>().UnmarshalBinary(state); if (errΔ1 != nil) {
            t.Errorf("could not unmarshal: %v", errΔ1);
            continue;
        }

        io.WriteString(h, g.@in.slice(len(g.@in) / 2));
        io.WriteString(h2, g.@in.slice(len(g.@in) / 2));

        var (actual, actual2) = (h.Sum(default), h2.Sum(default)); if (!bytes.Equal(actual, actual2)) {
            t.Errorf("sha1(%q) = 0x%x != marshaled 0x%x", g.@in, actual, actual2);
        }
    }
}

