internal static (slice<byte> sum, error err) safeSum(hash.Hash h) {
    slice<byte> sum = default;
    error err = default;
    GoFrame ᒐ = default;
    try {
        defer(() => {
            var r = recover(); if (r != nil) {
                err = fmt.Errorf("sum panic: %v"u8, r);
            }
        }, ref ᒐ);

        (sum, err) = (h.Sum(default), default);
    }
    catch (Exception ᒐex) when (GoFrame.IsPanic(ᒐex, out PanicException? ᒐp)) { GoFrame.Capture(ᒐp); }
    finally { ᒐ.Run(); }
    return (sum, err);
}

public static void TestLargeHashes(ж<testing.T> t) {
    cryptotest.TestAllImplementations(t, sha1ˢ, testLargeHashes);
}
internal static void testLargeHashes(ж<testing.T> t) {
    foreach (var (i, test) in range(largeUnmarshalTests)) {
        var h = New();
        var errΔ1 = h._<encoding.BinaryUnmarshaler>().UnmarshalBinary(slice<byte>(test.state)); if (errΔ1 != nil) {
            t.Errorf("test %d could not unmarshal: %v", i, errΔ1);
            continue;
        }

        var (sum, err) = safeSum(h);
        if (err != nil) {
            t.Errorf("test %d could not sum: %v", i, err);
            continue;
        }

        if (fmt.Sprintf("%x"u8, sum) != test.sum) {
            t.Errorf("test %d sum mismatch: expect %s got %x", i, test.sum, sum);
        }
    }
}

